[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ============================================
   RedRoom Fitness — Shared Styles
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --bg-primary: #111111;
  --bg-secondary: #1a1a1a;
  --bg-card: #1e1e1e;
  --bg-elevated: #252525;
  --text-primary: #ffffff;
  --text-secondary: #a0a0a0;
  --text-muted: #666666;
  --accent: #E63946;
  --accent-hover: #ff4d5a;
  --accent-dark: #b52d38;
  --accent-glow: rgba(230, 57, 70, 0.3);
  --border: #2a2a2a;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

/* Grain overlay */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  opacity: 0.025;
  pointer-events: none;
  z-index: 9999;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.1;
}

.section-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.section-subtitle {
  font-family: var(--font-body);
  font-size: clamp(0.95rem, 1.5vw, 1.125rem);
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
  font-size: 0.875rem;
  padding: 0.875rem 2rem;
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: white;
}
.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 8px 30px var(--accent-glow);
}

.btn-outline {
  background: transparent;
  color: white;
  border: 2px solid var(--accent);
}
.btn-outline:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.btn-white {
  background: white;
  color: var(--bg-primary);
}
.btn-white:hover {
  background: #f0f0f0;
  transform: translateY(-1px);
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1rem;
}

/* Red accent line */
.accent-line {
  width: 60px;
  height: 3px;
  background: var(--accent);
  margin-bottom: 1.5rem;
}

.accent-line-center {
  width: 60px;
  height: 3px;
  background: var(--accent);
  margin: 0 auto 1.5rem;
}

/* Top promo bar */
.top-bar {
  background: var(--accent);
  padding: 0.5rem 1.5rem;
  text-align: center;
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  font-weight: 500;
}
.top-bar a {
  color: white;
  text-decoration: none;
}
.top-bar a:hover {
  text-decoration: underline;
}

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0 2rem;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: white;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-logo .logo-red {
  color: var(--accent);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  list-style: none;
}
.nav-links a {
  font-family: var(--font-display);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  text-decoration: none;
  transition: color 0.2s;
  font-weight: 500;
}
.nav-links a:hover,
.nav-links a.active {
  color: white;
}
.nav-utility {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.nav-utility .btn {
  padding: 0.6rem 1.25rem;
  font-size: 0.75rem;
}

/* Mobile nav */
.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}
.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: white;
  margin: 5px 0;
  transition: all 0.3s;
}
.nav-toggle.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.nav-toggle.open span:nth-child(2) {
  opacity: 0;
}
.nav-toggle.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 999;
  padding: 2rem;
  overflow-y: auto;
}
.mobile-menu.open {
  display: block;
}
.mobile-menu a {
  display: block;
  font-family: var(--font-display);
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  text-decoration: none;
  padding: 1rem 0;
  border-bottom: 1px solid var(--border);
  transition: color 0.2s;
}
.mobile-menu a:hover {
  color: white;
}

/* Hero sections */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--bg-primary) 0%, #1a0a0b 50%, var(--bg-primary) 100%);
  z-index: 0;
}
.hero-bg::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 80%;
  height: 200%;
  background: radial-gradient(ellipse, var(--accent-glow) 0%, transparent 70%);
  opacity: 0.4;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 1400px;
  margin: 0 auto;
  padding: 4rem 2rem;
  width: 100%;
}
.hero-title {
  font-size: clamp(2.5rem, 7vw, 5.5rem);
  font-weight: 700;
  line-height: 1;
  margin-bottom: 1.5rem;
}
.hero-title .text-red {
  color: var(--accent);
}
.hero-subtitle {
  font-family: var(--font-body);
  font-size: clamp(1rem, 1.8vw, 1.25rem);
  color: var(--text-secondary);
  max-width: 560px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

/* Page hero (shorter) */
.page-hero {
  position: relative;
  padding: 6rem 2rem 4rem;
  overflow: hidden;
  background: linear-gradient(135deg, var(--bg-primary) 0%, #1a0a0b 100%);
}
.page-hero::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 50%;
  height: 100%;
  background: radial-gradient(ellipse at right, var(--accent-glow) 0%, transparent 70%);
  opacity: 0.3;
}
.page-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1400px;
  margin: 0 auto;
}
.page-hero .section-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
}

/* Sections */
.section {
  padding: 6rem 2rem;
}
.section-inner {
  max-width: 1400px;
  margin: 0 auto;
}
.section-dark {
  background: var(--bg-secondary);
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: all 0.3s ease;
}
.card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

/* Instructor card */
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: all 0.35s ease;
}
.instructor-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);
}
.instructor-avatar {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated), var(--bg-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
}
.instructor-info {
  padding: 1.25rem;
}
.instructor-name {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 0.25rem;
}
.instructor-location {
  color: var(--text-secondary);
  font-size: 0.85rem;
  margin-bottom: 0.75rem;
}
.instructor-book {
  color: var(--accent);
  font-family: var(--font-display);
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.2s;
}
.instructor-book:hover {
  color: var(--accent-hover);
}

/* Schedule table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
}
.schedule-table th {
  font-family: var(--font-display);
  text-transform: uppercase;
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 1rem 1.5rem;
  text-align: left;
  border-bottom: 2px solid var(--accent);
}
.schedule-table td {
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  font-size: 0.95rem;
}
.schedule-table tr:hover td {
  background: var(--bg-secondary);
}
.schedule-table .day-cell {
  font-family: var(--font-display);
  text-transform: uppercase;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--accent);
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  background: none;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 600;
  padding: 1.5rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  text-align: left;
  transition: color 0.2s;
}
.faq-question:hover {
  color: var(--accent);
}
.faq-icon {
  font-size: 1.5rem;
  transition: transform 0.3s ease;
  color: var(--accent);
  flex-shrink: 0;
  margin-left: 1rem;
}
.faq-item.open .faq-icon {
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.5rem;
}
.faq-answer p {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Toggle */
.toggle-group {
  display: inline-flex;
  background: var(--bg-card);
  border-radius: 8px;
  padding: 4px;
  border: 1px solid var(--border);
}
.toggle-btn {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 0.75rem 2rem;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 6px;
  transition: all 0.25s ease;
}
.toggle-btn.active {
  background: var(--accent);
  color: white;
}
.toggle-content {
  display: none;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active {
  display: block;
}

/* Carousel */
.carousel-container {
  position: relative;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  position: relative;
}
.carousel-slide-img {
  width: 100%;
  aspect-ratio: 16/7;
  object-fit: cover;
  background: linear-gradient(135deg, #1a0a0b, #2a1015, var(--bg-secondary));
}
.carousel-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(17,17,17,0.8) 0%, transparent 50%);
  display: flex;
  align-items: flex-end;
  padding: 2rem;
}
.carousel-caption {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 1.25rem;
  font-weight: 600;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(230, 57, 70, 0.9);
  border: none;
  border-radius: 50%;
  color: white;
  font-size: 1.25rem;
  cursor: pointer;
  z-index: 10;
  transition: all 0.25s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-btn:hover {
  background: var(--accent);
  transform: translateY(-50%) scale(1.1);
}
.carousel-btn-prev { left: 1.5rem; }
.carousel-btn-next { right: 1.5rem; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  padding: 1.5rem 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all 0.25s;
}
.carousel-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* Feature cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 2rem;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}
.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}
.feature-card:hover::before {
  transform: scaleX(1);
}
.feature-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}
.feature-icon {
  width: 48px;
  height: 48px;
  background: var(--accent-glow);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--accent);
}
.feature-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
}
.feature-desc {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* Two ways section */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 3rem 2.5rem;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}
.way-card:hover {
  border-color: var(--accent);
}
.way-card::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 40%;
  height: 100%;
  background: radial-gradient(ellipse at right, var(--accent-glow) 0%, transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
}
.way-card:hover::after {
  opacity: 0.3;
}
.way-label {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  font-size: 0.75rem;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 1rem;
}
.way-title {
  font-size: 1.75rem;
  margin-bottom: 1rem;
}
.way-desc {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Free trial CTA */
.cta-banner {
  background: var(--accent);
  padding: 5rem 2rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--accent-dark) 0%, var(--accent) 50%, var(--accent-dark) 100%);
}
.cta-banner-inner {
  position: relative;
  z-index: 1;
}
.cta-banner .section-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 1.5rem;
}

/* Newsletter */
.newsletter-section {
  padding: 5rem 2rem;
  background: var(--bg-secondary);
  text-align: center;
}
.newsletter-form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 2rem auto 0;
}
.newsletter-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-right: none;
  border-radius: 6px 0 0 6px;
  color: white;
  font-family: var(--font-body);
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s;
}
.newsletter-input:focus {
  border-color: var(--accent);
}
.newsletter-input::placeholder {
  color: var(--text-muted);
}
.newsletter-btn {
  padding: 0.875rem 1.5rem;
  background: var(--accent);
  color: white;
  border: 1px solid var(--accent);
  border-radius: 0 6px 6px 0;
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
  font-size: 0.8rem;
  cursor: pointer;
  transition: background 0.2s;
}
.newsletter-btn:hover {
  background: var(--accent-hover);
}
.newsletter-msg {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  min-height: 1.25rem;
}
.newsletter-msg.error {
  color: #ff6b6b;
}
.newsletter-msg.success {
  color: #51cf66;
}

/* Footer */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border);
  padding: 4rem 2rem 2rem;
}
.footer-inner {
  max-width: 1400px;
  margin: 0 auto;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-col-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 1.25rem;
}
.footer-links {
  list-style: none;
}
.footer-links li {
  margin-bottom: 0.6rem;
}
.footer-links a {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  transition: color 0.2s;
}
.footer-links a:hover {
  color: white;
}
.footer-country-select {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--text-secondary);
  padding: 0.5rem 0.75rem;
  font-family: var(--font-body);
  font-size: 0.85rem;
  cursor: pointer;
  outline: none;
  width: 100%;
}
.footer-country-select option {
  background: var(--bg-card);
  color: white;
}
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-copyright {
  color: var(--text-muted);
  font-size: 0.8rem;
}
.footer-socials {
  display: flex;
  gap: 1rem;
}
.footer-socials a {
  color: var(--text-muted);
  transition: color 0.2s;
  font-size: 1.1rem;
}
.footer-socials a:hover {
  color: var(--accent);
}

/* Filter buttons */
.filter-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.filter-btn {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.6rem 1.25rem;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}
.filter-btn:hover {
  border-color: var(--accent);
  color: white;
}
.filter-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: white;
}

/* Instructor grid */
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1.5rem;
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideInLeft {
  from { opacity: 0; transform: translateX(-30px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes slideInRight {
  from { opacity: 0; transform: translateX(30px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-fade-in {
  animation: fadeIn 0.6s ease forwards;
}

.animate-slide-left {
  animation: slideInLeft 0.6s ease forwards;
}

.animate-slide-right {
  animation: slideInRight 0.6s ease forwards;
}

/* Staggered children */
.stagger > * {
  opacity: 0;
  animation: fadeIn 0.5s ease forwards;
}
.stagger > *:nth-child(1) { animation-delay: 0.1s; }
.stagger > *:nth-child(2) { animation-delay: 0.2s; }
.stagger > *:nth-child(3) { animation-delay: 0.3s; }
.stagger > *:nth-child(4) { animation-delay: 0.4s; }
.stagger > *:nth-child(5) { animation-delay: 0.5s; }
.stagger > *:nth-child(6) { animation-delay: 0.6s; }

/* Lifestyle carousel mini */
.lifestyle-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.lifestyle-item {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-elevated), var(--bg-secondary));
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  transition: transform 0.3s;
}
.lifestyle-item:hover {
  transform: scale(1.03);
}
.lifestyle-item-inner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
  text-align: center;
  padding: 1rem;
  background: linear-gradient(135deg, rgba(230,57,70,0.05), transparent);
}

/* Digital feature */
.digital-feature {
  display: flex;
  gap: 3rem;
  align-items: center;
  padding: 3rem 0;
  border-bottom: 1px solid var(--border);
}
.digital-feature:last-child {
  border-bottom: none;
}
.digital-feature-num {
  font-family: var(--font-display);
  font-size: 4rem;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.3;
  flex-shrink: 0;
  line-height: 1;
}
.digital-feature-content {
  flex: 1;
}
.digital-feature-title {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}
.digital-feature-desc {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Red glow decorative element */
.red-glow {
  position: absolute;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, var(--accent-glow) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

/* Responsive */
@media (max-width: 1200px) {
  .nav-links { display: none; }
  .nav-toggle { display: block; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .section { padding: 4rem 1.25rem; }
  .hero { min-height: 70vh; }
  .hero-content { padding: 3rem 1.25rem; }
  .page-hero { padding: 4rem 1.25rem 3rem; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-right: 1px solid var(--border); border-radius: 6px; }
  .newsletter-btn { border-radius: 6px; }
  .feature-grid { grid-template-columns: 1fr; }
  .instructor-grid { grid-template-columns: 1fr 1fr; }
  .lifestyle-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
  .digital-feature { flex-direction: column; gap: 1rem; }
  .digital-feature-num { font-size: 2.5rem; }
  .cta-banner { padding: 3.5rem 1.25rem; }
  .carousel-btn { width: 36px; height: 36px; font-size: 1rem; }
  .carousel-btn-prev { left: 0.75rem; }
  .carousel-btn-next { right: 0.75rem; }
}

@media (max-width: 480px) {
  .instructor-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 2rem; }
  .toggle-btn { padding: 0.6rem 1.25rem; font-size: 0.75rem; }
}

/* Utility */
.text-red { color: var(--accent); }
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }
.mt-2 { margin-top: 2rem; }
.mb-2 { margin-bottom: 2rem; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.gap-1 { gap: 1rem; }
.gap-2 { gap: 2rem; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
